-- Class notes synopsis batch 5: Bladderwrack through California Poppy

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Bladderwrack</strong> (Fucus vesiculosus) is an <strong>iodine-rich</strong> seaweed - highest in iodine - traditionally used as a tincture and in capsules for <strong>thyroid</strong> support and <strong>hypothyroid</strong> conditions, including <strong>thyroid-related depression</strong>; the constitutional picture is <strong>thyroid hypofunction</strong> with tendency toward <strong>obesity</strong>, <strong>fatty accumulation of the heart</strong>, and <strong>malnutrition with mineral deficiencies</strong>. It supports <strong>lymphatic movement</strong>, reduces <strong>inflammation</strong>, supplies <strong>trace minerals</strong>, and is also used as a topical <strong>pain oil</strong>; it has been studied to bind certain <strong>heavy metals</strong> and <strong>chelate</strong> them from the body - useful for <strong>detox</strong>, but not a standalone solution. Featured in Jill Stansbury's <strong>Hashimoto's</strong> tincture in equal parts with <a href="?herb=877"><strong>Guggul</strong></a> (Commiphora Mukul), <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=14"><strong>Panax Ginseng</strong></a>, and <a href="?herb=31"><strong>Blue Flag</strong></a> (Iris versicolor). Also functions as a <strong>kidney/bladder tonic</strong> alongside <a href="?herb=122"><strong>Dandelion</strong></a> leaf, <a href="?herb=58"><strong>Goldenrod</strong></a>, and <a href="?herb=28"><strong>Cleavers</strong></a>.$$
WHERE common_name = 'Bladderwrack';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Borage</strong> is a <strong>nervine</strong> for <strong>anxiety</strong> and courage, and a <strong>flower essence</strong> for courage and strength - a spirit remedy for <strong>depression</strong>, particularly used with children for courage; associated with Jupiter.$$
WHERE common_name = 'Borage';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Bugleweed</strong> (Lycopus virginicus) is a <strong>metabolic cooler</strong> for <strong>thyroid</strong> balance; the constitutional picture is the <strong>goiter</strong> phase with <strong>tachycardia</strong>, mild <strong>respiratory dysfunction</strong> (shallow breathing), <strong>circulatory issues</strong>, <strong>anxiety</strong>, <strong>passive capillary hemorrhage</strong>, and <strong>palpitations</strong>; interchangeable with <a href="?herb=131"><strong>Motherwort</strong></a> for cardiovascular support. Cools <strong>lower GI excess</strong> alongside <a href="?herb=853"><strong>Silk Tassel</strong></a>, <a href="?herb=119"><strong>Bayberry</strong></a>, and <a href="?herb=154"><strong>Rhubarb</strong></a> root; cools the <strong>anabolic tendency</strong> in <strong>liver excess</strong>.$$
WHERE common_name = 'Bugleweed';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Bupleurum</strong> (Chai Hu) is the primary herb for <strong>Liver Qi stagnation</strong>, used in classical formulas Xiao Yao San and Shu Gan San; <strong>Liver Qi stagnation</strong> symptoms include <strong>depression</strong>, <strong>frustration</strong>, <strong>pain in the sides</strong>, <strong>PMS</strong>, <strong>decision-making difficulty</strong>, and <strong>hormonal dysregulation</strong>.$$
WHERE common_name = 'Bupleurum';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Burdock</strong> is a <strong>cooling</strong>, ultimately <strong>drying</strong> (Tilgner: "distributes moisture but is ultimately drying"), <strong>bitter</strong>, <strong>sweet</strong>, <strong>nourishing</strong> <strong>alterative</strong> - formerly called a "blood cleanser" - that alters the body from unhealthy to healthy via the channels of elimination: <strong>bowel</strong>, <strong>kidney</strong>, <strong>skin</strong>, and <strong>liver</strong>. As the least bitter of the bitters, it is <strong>hepatic</strong> and <strong>cholagogue</strong> (stimulates bile and digestive secretions including HCl and pancreatic juices); safe and nourishing for the <strong>liver</strong>; specific indications include <strong>gallstones</strong>, <strong>biliary disease</strong>, <strong>fatty liver disease</strong>, <strong>hyperlipidemia</strong>, <strong>chronic acne</strong> and <strong>skin disorders</strong>, <strong>fatigue</strong>, <strong>malaise</strong>, <strong>indigestion</strong>, and <strong>constipation</strong>; it enhances liver detox pathways, clearing excess hormones and cellular waste. It is both <strong>prebiotic</strong> and <strong>probiotic</strong>, high in inulin - feeds beneficial gut bacteria alongside chicory and <a href="?herb=122"><strong>Dandelion</strong></a> root - and supports <strong>gut health</strong> and <strong>microbiome</strong> diversity; used for <strong>digestive ailments</strong> including <strong>diarrhea</strong> and <strong>colic</strong> in traditional Black American herbalism, and for <strong>stomach ache</strong> and <strong>cramp</strong>. As a blood and <strong>lymphatic</strong> clearing alterative: clears excess <strong>estrogen</strong> (with <a href="?herb=40"><strong>Sarsaparilla</strong></a>), excess <strong>androgens</strong> (with <a href="?herb=39"><strong>Figwort</strong></a>, <a href="?herb=40"><strong>Sarsaparilla</strong></a>, and <a href="?herb=37"><strong>Yellow Dock</strong></a>), and is an alterative for <strong>inflammation</strong> in <strong>liver disease</strong>, <strong>rheumatoid arthritis</strong>, and accumulation with aging; used in early-stage <strong>cancer</strong> anti-cancer formula to quickly change the environment, and listed as a <strong>lymphatic</strong> herb for cancer support. Prepared as an infusion for <strong>tuberculosis (TB)</strong> in the African American Materia Medica. Indicated for <strong>endometriosis</strong> and as a metabolic support herb for <strong>perimenopause</strong>, supporting all elimination pathways. Constitutionally: cold constitution alterative alongside <a href="?herb=92"><strong>Slippery Elm</strong></a> and <a href="?herb=45"><strong>Marshmallow</strong></a> root with <a href="?herb=167"><strong>Cinnamon</strong></a> or Cardamom (cold body tends toward sluggish metabolism and bowel stagnation); wet constitution alterative alongside <a href="?herb=122"><strong>Dandelion</strong></a> root, <a href="?herb=40"><strong>Sarsaparilla</strong></a>, and <strong>Baptisia</strong> (Wild Indigo); diuretic cooler for <strong>kidney excess</strong> alongside Shepherd's Purse, <a href="?herb=151"><strong>Horsetail</strong></a>, and <a href="?herb=122"><strong>Dandelion</strong></a> leaf; cools <strong>liver excess</strong> (the anabolic tendency) alongside <a href="?herb=133"><strong>Bugleweed</strong></a>, <a href="?herb=206"><strong>Milk Thistle</strong></a>, and <a href="?herb=591"><strong>Devil's Club</strong></a>; cools <strong>skin excess</strong> via liver cooling. Topically, a poultice of <strong>Burdock</strong>, <a href="?herb=122"><strong>Dandelion</strong></a>, and <a href="?herb=28"><strong>Cleavers</strong></a> is used for <strong>breast cysts</strong>. Partners with <a href="?herb=122"><strong>Dandelion</strong></a> root as a liver tonic (toasted together as a coffee replacement). Featured in formulas: liver tea with <a href="?herb=225"><strong>Astragalus</strong></a>, <a href="?herb=122"><strong>Dandelion</strong></a>, Orange Peel, <a href="?herb=76"><strong>Fennel</strong></a>, and <a href="?herb=78"><strong>Licorice</strong></a>; Hoffmann <strong>psoriasis</strong> formula with <a href="?herb=37"><strong>Yellow Dock</strong></a> and <strong>Baical Skullcap</strong>; decoction with <a href="?herb=37"><strong>Yellow Dock</strong></a> for <strong>PTSD</strong>, <strong>constipation</strong>, and <strong>elevated cortisol</strong>; combined with <a href="?herb=92"><strong>Slippery Elm</strong></a> and <a href="?herb=154"><strong>Rhubarb</strong></a> as demulcent, nourishing, alterative, fiber blend for gut impact; urinary glycerite with <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=122"><strong>Dandelion</strong></a> leaf, and <a href="?herb=55"><strong>Peppermint</strong></a> to move water and remove waste; reproductive/thyroid tincture with <a href="?herb=2238"><strong>Peony</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, and <a href="?herb=2229"><strong>Gotu Kola</strong></a>. As an anchor herb in chronic-pain lymph formulas, the dose is middle of MM range (60 drops / 22 ml out of 60 ml) for a 150 lb chronic patient with weakened vitality; especially suited as a single herb where multiple medications require a minimal complexity approach.$$
WHERE common_name = 'Burdock';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Cacao</strong> is a <strong>nervine stimulant</strong> containing <strong>theobromine</strong> - which acts like caffeine but is distinct - and is listed among <strong>blood sugar</strong> herbs to consider.$$
WHERE common_name = 'Cacao';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Calamus</strong> is a <strong>carminative</strong> for <strong>hypochlorhydria</strong>; used with <a href="?herb=207"><strong>Wood Betony</strong></a> in a Monk's Tea Blend Tincture taken for going out on a walk.$$
WHERE common_name = 'Calamus';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Calendula</strong> (Pot Marigold) is a light-bearing plant that follows the sun - one of the essential herbs of the Middle Ages in western Europe - used for <strong>seasonal affective disorder (SAD)</strong> and <strong>winter/low-light depression</strong>; the infused <strong>oil</strong> is <strong>vulnerary</strong>, <strong>emollient</strong>, cools <strong>inflammation</strong>, and is good for <strong>cold stagnant depression</strong>. As a <strong>gentle whole-body lymphatic</strong>, it is chosen over <a href="?herb=981"><strong>Red Root</strong></a> when more nourishing and moistening to tissues is needed - dose 4 ml (2 parts) at the lower MM range (15 drops) for sensitive patients; serves as a <strong>lymph stimulant</strong> for cold constitution and a <strong>lymph alterative</strong> for hot constitution. Core actions: <strong>vulnerary</strong>, <strong>antimicrobial</strong>, <strong>anti-inflammatory</strong>, <strong>antifungal</strong>, <strong>demulcent</strong>, <strong>emollient</strong>, <strong>astringent</strong>, <strong>anodyne</strong>, <strong>antibacterial</strong>, <strong>moistening</strong>, and immune-stimulating for <strong>mucous membranes</strong>. For wounds, cuts, and scrapes (applied as tincture, poultice, compress, or salve - salves better for minor cuts; wounds needing to dry should not be kept moist); for poorly healing <strong>stasis wounds</strong> and <strong>poor circulation</strong>, dose is tincture 1-4 ml 3x/day or infusion 3x/day (Fresh 1:2, Dry 1:5 60% alcohol); improves <strong>skin's protective barrier</strong> and supports <strong>collagen synthesis</strong>; wound wash blend includes <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=85"><strong>Plantain</strong></a>, <a href="?herb=82"><strong>Lavender</strong></a>, <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=2437"><strong>Self Heal</strong></a>, <a href="?herb=88"><strong>Chickweed</strong></a>, and <a href="?herb=81"><strong>St. John's Wort</strong></a> (steep 45 minutes to an hour, strain well, put in thermos); for <strong>burns</strong>, used alongside <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=202"><strong>Aloe</strong></a>, and <a href="?herb=81"><strong>St. John's Wort</strong></a>; for wounds that don't heal in pets (with Daisies) and in topical spray for hot spots with <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=22"><strong>Burdock</strong></a>, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=122"><strong>Dandelion</strong></a>, and <a href="?herb=81"><strong>St. John's Wort</strong></a>. Calendula is <strong>antifungal</strong> against <strong>yeast infections</strong>, <strong>thrush</strong>, <strong>GI candidiasis</strong>, <strong>athlete's foot</strong>, and <strong>toenail fungus</strong>; its resins are not extractable in cold water alone - use alcohol tincture or hot water infusion for antifungal and vulnerary resins. Internally for <strong>gut healing</strong>: <strong>GI vulnerary</strong> for <strong>leaky gut</strong>, <strong>peptic ulcer</strong>, and <strong>gastric mucosa</strong>; ground with <a href="?herb=85"><strong>Plantain</strong></a> and <a href="?herb=45"><strong>Marshmallow</strong></a> into applesauce before meals to seal tight junctions; in ulcer-healing formula with <a href="?herb=85"><strong>Plantain</strong></a> and <a href="?herb=45"><strong>Marshmallow</strong></a> root; <strong>GI astringent</strong> for <strong>diarrhea</strong>; useful for <strong>hot dry constipation</strong> (not as mucilaginous as others). For immunity and healthy aging: moistening while stimulating immune function, in formula with <a href="?herb=225"><strong>Astragalus</strong></a>, <a href="?herb=1528"><strong>Jujubes</strong></a>, <a href="?herb=1548"><strong>Goji berries</strong></a>, <a href="?herb=852"><strong>Shatavari</strong></a>, <a href="?herb=26"><strong>Echinacea</strong></a>, and <a href="?herb=99"><strong>Myrrh</strong></a> to stimulate immune function while addressing waste accumulation. For chronic <strong>respiratory membrane</strong> repair: nourishing, moistening, anti-inflammatory in repair tea with <a href="?herb=151"><strong>Horsetail</strong></a> and <a href="?herb=85"><strong>Plantain</strong></a>. For skin: deeply conditioning, moisturizing, <strong>reduces wrinkles</strong>, hydrates <strong>mucous membranes</strong>, indicated for <strong>dry skin</strong>; infused oil maintains skin pH and nourishes tissue; for <strong>skin deficiency</strong> (liver deficiency), stimulates circulation alongside <a href="?herb=123"><strong>Prickly Ash</strong></a>, <a href="?herb=41"><strong>Queen's Delight</strong></a> (Stilingia), and <a href="?herb=30"><strong>Goldenseal</strong></a> root; in a <strong>dermatitis</strong> formula with <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=1009"><strong>Dong Quai</strong></a>, and <a href="?herb=2229"><strong>Gotu Kola</strong></a>; Calendula vinegar as a conditioning hair rinse. For <strong>autoimmune disease</strong> with ECM and <strong>fibromyalgia</strong>. Topical and perineal: sitz bath with <a href="?herb=54"><strong>Elecampane</strong></a>, <a href="?herb=849"><strong>Rose</strong></a> petals, and <a href="?herb=44"><strong>Yarrow</strong></a>; perineal wash with <a href="?herb=85"><strong>Plantain</strong></a>, <a href="?herb=849"><strong>Rose</strong></a>, and <a href="?herb=44"><strong>Yarrow</strong></a>; <strong>vaginitis</strong> infused bath with <a href="?herb=84"><strong>Chamomile</strong></a>; <strong>postpartum</strong> topical tissue repair; neti pot infusion for sinus <strong>infection</strong>. Used in nutritional <strong>fertility</strong> teas with <a href="?herb=155"><strong>Red Raspberry</strong></a>.$$
WHERE common_name = 'Calendula';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>California Bay Laurel</strong> - smell the leaves for <strong>headaches</strong> on the trail.$$
WHERE common_name = 'California Bay Laurel';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>California Poppy</strong> (aerial parts) is a <strong>hypnotic</strong>, <strong>analgesic</strong>, <strong>anodyne</strong>, <strong>anxiolytic</strong>, <strong>sedative</strong>, and <strong>relaxing nervine</strong> - trance-inducing, a little more than simple sedatives - that decreases pain and increases quality of sleep and will not sedate an unwilling person; good during the day to smooth out the edges; smaller doses for kids. <strong>Caution with driving as these herbs can also be sedative.</strong> It acts specifically on <strong>smooth and skeletal muscles</strong> for <strong>low-grade chronic pain</strong>, <strong>menstrual cramps</strong>, and <strong>muscle cramps and spasms</strong>; provides pain relief and relaxation for the <strong>urinary system</strong>; analgesic and sedative for <strong>bone aches</strong> in flu; and is useful for <strong>sleep conditions</strong>, <strong>headaches</strong>, <strong>tension</strong>, <strong>addiction recovery</strong>, and <strong>pain-induced insomnia</strong>. Indicated for <strong>insomnia in pregnancy</strong> - rotate remedies once no longer effective; also for sleep support after pregnancy. As a <strong>nervine</strong> for <strong>rheumatoid arthritis</strong>, <strong>asthma</strong>, and <strong>emphysema</strong>. An antidote to <strong>over-caffeination</strong>; used with <a href="?herb=136"><strong>Catnip</strong></a> as a tincture and as a fresh aerial parts tea; helpful for children with <strong>nervous system issues</strong> alongside <a href="?herb=136"><strong>Catnip</strong></a> and Magnesium. Possibly helpful for easing <strong>withdrawal</strong> symptoms alongside <a href="?herb=81"><strong>St. John's Wort</strong></a>. An <strong>alkaloidal</strong> plant - alkaloids are not well extracted by water; an alcohol-based tincture is the appropriate preparation for its analgesic alkaloids; add 5-10% vinegar when tincturing (vinegar also works well as a tincture alternative). <strong>DO NOT use with sedative medication. Most hypnotics are also hypotensives.</strong> Featured in a sleep formula: 2 parts <a href="?herb=145"><strong>Valerian</strong></a>, 1 part California Poppy, 1/2 part <a href="?herb=73"><strong>Hawthorn</strong></a> leaf and flower, 1/2 part <a href="?herb=13"><strong>Tulsi</strong></a>, 1/2 part <a href="?herb=45"><strong>Marshmallow</strong></a>, 1/2 part <a href="?herb=167"><strong>Cinnamon</strong></a>.$$
WHERE common_name = 'California Poppy';
